  authoredSql: {"534":"SELECT player_id, event_date,\n       SUM(games_played) OVER (\n           PARTITION BY player_id ORDER BY event_date\n           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n       ) AS games_played_so_far\nFROM Activity;","550":"WITH FirstLogin AS (\n    SELECT player_id, MIN(event_date) AS first_date\n    FROM Activity GROUP BY player_id\n)\nSELECT ROUND(AVG(CASE WHEN a.player_id IS NULL THEN 0 ELSE 1 END), 2) AS fraction\nFROM FirstLogin AS f\nLEFT JOIN Activity AS a\n  ON a.player_id = f.player_id\n AND a.event_date = DATE_ADD(f.first_date, INTERVAL 1 DAY);","577":"SELECT e.name, b.bonus\nFROM Employee AS e\nLEFT JOIN Bonus AS b ON b.empId = e.empId\nWHERE b.bonus < 1000 OR b.bonus IS NULL;","586":"SELECT customer_number\nFROM Orders\nGROUP BY customer_number\nORDER BY COUNT(*) DESC\nLIMIT 1;"},
